const rawOutput = String($('Agent Entretien').item.json.output || '')
const contextData = $('Preparer Contexte Entretien').item.json
const autorisationFin = contextData.autorisationFin === true

function parseAgentOutput(raw) {
  const trimmed = raw.trim()
  try {
    const parsed = JSON.parse(trimmed)
    if (parsed && typeof parsed === 'object') return parsed
  } catch {}
  const firstBrace = trimmed.indexOf('{')
  const lastBrace = trimmed.lastIndexOf('}')
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    try {
      const parsed = JSON.parse(trimmed.slice(firstBrace, lastBrace + 1))
      if (parsed && typeof parsed === 'object') return parsed
    } catch {}
  }
  return { output: trimmed, isFinished: /\[FIN\]/i.test(trimmed), interactiveQuestion: null }
}

function normalizeInteractiveQuestion(question) {
  if (!question || typeof question !== 'object') return null
  const type = question.type === 'checkbox' ? 'checkbox' : question.type === 'radio' ? 'radio' : null
  if (!type || !Array.isArray(question.options)) return null
  const options = question.options
    .map((option) => {
      if (typeof option === 'string') return { label: option, value: option }
      return {
        label: String(option?.label || option?.text || option?.value || '').trim(),
        value: String(option?.value || option?.label || option?.text || '').trim(),
      }
    })
    .filter((option) => option.label && option.value)
    .filter((option) => {
      const label = option.label.toLowerCase()
      const value = option.value.toLowerCase()
      return label !== '[fin]' && value !== '[fin]' && label !== 'fin' && value !== 'fin'
    })
  if (options.length < 2) return null
  return { type, options }
}

function normalizeText(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
}

const parsed = parseAgentOutput(rawOutput)

let output = String(parsed.output || parsed.message || rawOutput)
  .replace(/\[FIN\]/gi, '')
  .trim()

const normalizedRaw = normalizeText(rawOutput)

const looksFinished =
  parsed.isFinished === true ||
  /\[FIN\]/i.test(rawOutput) ||
  normalizedRaw.includes('entretien est termine') ||
  normalizedRaw.includes('interview is complete') ||
  normalizedRaw.includes('merci beaucoup pour cette conversation') ||
  normalizedRaw.includes('merci pour cette conversation') ||
  normalizedRaw.includes('merci pour vos reponses') ||
  normalizedRaw.includes('thank you for your answers') ||
  normalizedRaw.includes('thanks for this conversation')

const lang = contextData.interviewLanguage === 'en' ? 'en' : 'fr'
const topics = contextData.exploredTopics || {}
const currentStudentInput = String(contextData.chatInput || '').trim()

const completionText =
  lang === 'en'
    ? 'The interview is complete. Thank you for your answers.'
    : "L'entretien est terminé. Merci pour vos réponses."

const applicationQuestion =
  lang === 'en'
    ? 'What did you think of this interview? Did it meet your expectations?'
    : "Qu'avez-vous pensé de cet entretien ? A-t-il correspondu à vos attentes ?"

let isFinished = autorisationFin && looksFinished

if (looksFinished && !autorisationFin) {
  if (!topics.decision) {
    output =
      lang === 'en'
        ? 'Before finishing, can you tell me about a recent moment when you had to make an important choice or decision in your studies?'
        : "Avant de terminer, pouvez-vous me parler d'un moment récent où vous avez dû faire un choix ou prendre une décision importante dans vos études ?"
  } else if (!topics.relations) {
    output =
      lang === 'en'
        ? 'Before finishing, can you tell me about a recent situation with classmates, group work, or a misunderstanding?'
        : "Avant de terminer, pouvez-vous me parler d'une situation récente avec des camarades, un travail de groupe ou un malentendu ?"
  } else if (!topics.stress) {
    output =
      lang === 'en'
        ? 'Before finishing, can you describe a recent moment when you felt stress or pressure in your studies?'
        : "Avant de terminer, pouvez-vous décrire un moment récent où vous avez ressenti du stress ou de la pression dans vos études ?"
  } else {
    output = applicationQuestion
  }
}

// Detection generique : si l agent genere une question deja posee et deja repondue, on redirige
// Fonctionne quelque soit la reponse de l etudiant, sans correspondance de mots-cles
const rawHistory = $('Webhook').item.json.body.conversationHistory || []

function questionKey(text) {
  return normalizeText(String(text || '')).replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 70)
}

const currentKey = questionKey(output)
let agentRepeatedAnsweredQuestion = false

if (currentKey.length > 20) {
  for (let i = 0; i < rawHistory.length; i++) {
    const msg = rawHistory[i]
    const msgType = msg.role === 'ai' || msg.type === 'ai' ? 'ai' : 'human'
    const msgContent = String(msg.content || msg.message || msg.text || '')
    if (msgType === 'ai' && questionKey(msgContent) === currentKey) {
      const nextMsg = rawHistory[i + 1]
      const hasHistoryReply =
        nextMsg &&
        nextMsg.role !== 'ai' && nextMsg.type !== 'ai' &&
        String(nextMsg.content || nextMsg.message || nextMsg.text || '').trim().length > 3
      const hasCurrentReply = i === rawHistory.length - 1 && currentStudentInput.length > 3
      if (hasHistoryReply || hasCurrentReply) {
        agentRepeatedAnsweredQuestion = true
        break
      }
    }
  }
}

if (agentRepeatedAnsweredQuestion) {
  if (autorisationFin) {
    return [{
      json: {
        output: completionText,
        isFinished: true,
        interactiveQuestion: null,
        analysisData: null,
      },
    }]
  }
  if (!topics.decision) {
    output =
      lang === 'en'
        ? 'Before finishing, can you tell me about a recent moment when you had to make an important choice in your studies?'
        : "Avant de terminer, pouvez-vous me parler d'un moment récent où vous avez dû faire un choix important dans vos études ?"
  } else if (!topics.relations) {
    output =
      lang === 'en'
        ? 'Before finishing, can you tell me about a recent situation with classmates or group work?'
        : "Avant de terminer, pouvez-vous me parler d'une situation récente avec des camarades ou un travail de groupe ?"
  } else if (!topics.stress) {
    output =
      lang === 'en'
        ? 'Before finishing, can you describe a recent moment when you felt stress or pressure?'
        : "Avant de terminer, pouvez-vous décrire un moment récent où vous avez ressenti du stress ou de la pression ?"
  } else {
    return [{
      json: {
        output: completionText,
        isFinished: autorisationFin,
        interactiveQuestion: null,
        analysisData: null,
      },
    }]
  }
}

return [{
  json: {
    output,
    isFinished,
    interactiveQuestion: isFinished ? null : normalizeInteractiveQuestion(parsed.interactiveQuestion),
    analysisData: null,
  },
}]

const sessionId = $('Webhook').item.json.body.sessionId || 'default'
const bodyHistory = $('Webhook').item.json.body.conversationHistory

let conversationHistory = []

if (Array.isArray(bodyHistory) && bodyHistory.length > 0) {
  conversationHistory = bodyHistory
    .map((message) => ({
      type: message.role === 'ai' ? 'ai' : message.type === 'ai' ? 'ai' : 'human',
      content: String(message.content || message.message || message.text || '').trim(),
    }))
    .filter((message) => message.content)
}

try {
  const chatInput = $('Webhook').item.json.body.chatInput
  const agentOutput = $('Agent Entretien').item.json.output
  const parsedOutput = (() => {
    try {
      const parsed = JSON.parse(String(agentOutput || '').trim())
      return parsed?.output || agentOutput
    } catch {
      return agentOutput
    }
  })()

  if (chatInput && !conversationHistory.some((msg) => msg.type === 'human' && msg.content === chatInput)) {
    conversationHistory.push({ type: 'human', content: chatInput })
  }
  if (parsedOutput && !conversationHistory.some((msg) => msg.type === 'ai' && msg.content === parsedOutput)) {
    conversationHistory.push({ type: 'ai', content: String(parsedOutput).replace(/\[FIN\]/gi, '').trim() })
  }
} catch (error) {
  console.log('Current turn extraction error:', error.message)
}

if (conversationHistory.length === 0) {
  try {
    const memoryNode = $('Memoire Conversation')
    if (memoryNode && memoryNode.all) {
      const memoryItems = memoryNode.all()
      for (const item of memoryItems) {
        if (item.json && item.json.chatHistory) {
          for (const message of item.json.chatHistory) {
            conversationHistory.push({
              type: message.type || message.role,
              content: message.content || message.text,
            })
          }
        }
      }
    }
  } catch (error) {
    console.log('Memory extraction error:', error.message)
  }
}

const formattedConversation = conversationHistory
  .filter((msg) => msg.content)
  .map((msg) => {
    const role = msg.type === 'ai' ? 'Assistant' : 'Etudiant'
    return role + ': ' + msg.content
  })
  .join('\n\n')

return [{
  json: {
    formattedConversation,
    conversationHistory,
    sessionId,
  },
}]

const items = $input.all()

if (!items || items.length === 0) {
  return [{ json: { output: "L'entretien est termine. Merci pour vos reponses.", isFinished: true, interactiveQuestion: null, analysisData: null } }]
}

let analysisData = null
const rawReport = items[0].json.output || ''
const validationErrors = items[0].json.validationErrors || []
const validationWarnings = items[0].json.validationWarnings || []

function parseJsonObject(raw) {
  let cleaned = String(raw || '')
    .replace(/^[\s\S]*?```json\s*/i, '')
    .replace(/^[\s\S]*?```\s*/i, '')
    .replace(/\s*```[\s\S]*$/i, '')
    .trim()
  const firstBrace = cleaned.indexOf('{')
  const lastBrace = cleaned.lastIndexOf('}')
  if (firstBrace !== -1 && lastBrace > firstBrace) cleaned = cleaned.slice(firstBrace, lastBrace + 1)
  cleaned = cleaned.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
  return JSON.parse(cleaned)
}

try {
  analysisData = parseJsonObject(rawReport)
  if (!analysisData || typeof analysisData !== 'object') throw new Error('Resultat JSON non-objet')
  if (!analysisData.traits || !Array.isArray(analysisData.traits)) {
    if (analysisData.big_five && Array.isArray(analysisData.big_five)) analysisData.traits = analysisData.big_five
    else if (analysisData.scores && Array.isArray(analysisData.scores)) analysisData.traits = analysisData.scores
    else throw new Error('Pas de tableau traits trouve')
  }
  const validTraits = analysisData.traits.filter((t) => t && typeof t === 'object' && t.name && (t.score !== undefined || t.value !== undefined))
  if (validTraits.length === 0) throw new Error('Aucun trait valide trouve')
  analysisData.traits = validTraits.map((t) => ({
    name: t.name || t.trait || t.label || 'Trait',
    score: Math.max(1, Math.min(10, Math.round(Number(t.score || t.value || t.note || 5)))),
    analysis: t.analysis || t.description || '',
    interpretation: t.interpretation || '',
    confidence: t.confidence || 'moyen',
    confidence_reason: t.confidence_reason || '',
    evidence: t.evidence || '',
    observed_indicators: Array.isArray(t.observed_indicators) ? t.observed_indicators : [],
  }))
  if (!analysisData.executive_summary) {
    analysisData.executive_summary = {
      overview: analysisData.overview || '',
      dominant_strengths: analysisData.dominant_strengths || '',
      watch_points: analysisData.watch_points_summary || '',
      relational_style: analysisData.relational_style || '',
    }
  }
  if (!analysisData.emotional_profile) {
    analysisData.emotional_profile = {
      dominant_emotion: 'neutre',
      emotional_stability: 5,
      emotional_summary: '',
    }
  }
  if (!analysisData.global_synthesis) {
    analysisData.global_synthesis = {
      general_functioning_style: '',
      main_strengths: [],
      watch_points: [],
      development_potential: '',
    }
  }
  if (!Array.isArray(analysisData.recommendations)) analysisData.recommendations = []
  const scores = analysisData.traits.map((t) => Number(t.score))
  if (!analysisData.score_validation) {
    analysisData.score_validation = {
      min_score: Math.min(...scores),
      max_score: Math.max(...scores),
      spread: Math.max(...scores) - Math.min(...scores),
      coherence_notes: 'Scores normalises.',
      validation_passed: validationErrors.length === 0,
      errors: validationErrors,
      warnings: validationWarnings,
    }
  } else {
    analysisData.score_validation.validation_passed = validationErrors.length === 0
    analysisData.score_validation.errors = validationErrors
    analysisData.score_validation.warnings = validationWarnings
  }
} catch (e) {
  console.log('Erreur parsing/validation JSON:', e.message)
  console.log('Reponse brute:', String(rawReport).slice(0, 500))
  analysisData = null
}

const hasUsableAnalysis =
  analysisData &&
  Array.isArray(analysisData.traits) &&
  analysisData.traits.length >= 5

return [{
  json: {
    output: hasUsableAnalysis
      ? "L'entretien est terminé. Merci pour vos réponses."
      : "Merci, j'ai bien noté votre réponse. Le rapport n'a pas pu être généré correctement, je vais relancer l'analyse.",
    isFinished: hasUsableAnalysis,
    interactiveQuestion: null,
    analysisData: hasUsableAnalysis ? analysisData : null,
  }
}]

const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { output: '{}', validationPassed: false, validationErrors: ['Aucune entrée'] } }];
}

// Detect interview language from context
let interviewLanguage = 'fr';
try {
  interviewLanguage = $('Preparer Contexte Entretien').item.json.interviewLanguage === 'en' ? 'en' : 'fr';
} catch (e) {}
const isEN = interviewLanguage === 'en';

const rawOutput = items[0].json.output || '{}';
let analysisData = null;

function cleanAndParseJson(raw) {
  let cleaned = String(raw || '')
    .replace(/^[\s\S]*?```json\s*/i, '')
    .replace(/^[\s\S]*?```\s*/i, '')
    .replace(/\s*```[\s\S]*$/i, '')
    .trim();
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }
  cleaned = cleaned.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
  return JSON.parse(cleaned);
}

try {
  analysisData = cleanAndParseJson(rawOutput);
} catch (e) {
  console.log('[VALIDATION] Impossible de parser le JSON:', e.message);
  return [{ json: { output: rawOutput, validationPassed: false, validationErrors: ['JSON invalide'] } }];
}

if (!analysisData || !Array.isArray(analysisData.traits)) {
  return [{ json: { output: rawOutput, validationPassed: false, validationErrors: ['Pas de tableau traits'] } }];
}

const errors = [];
const warnings = [];
const traits = analysisData.traits;

let conversationText = '';
try {
  conversationText = $('Extraire Historique').item.json.formattedConversation || '';
} catch (e) {
  conversationText = '';
}

const normalizedConversationText = conversationText
  .toLowerCase()
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '');

conversationText = conversationText.toLowerCase();

const anxietyMarkers = [
  'anxious', 'anxiety', 'nervous', 'worried', 'worry', 'overthink', 'overthinking',
  'scared', 'fear', 'afraid', 'judged', 'not good enough', 'self-doubt',
  'stress', 'stressed', 'panic', 'mistake', 'mistakes', 'embarrassed',
  'too sensitive', 'hide my feelings', 'kept it to myself', 'reassurance',
  'anxieux', 'anxieuse', 'anxiete', 'nerveux', 'nerveuse', 'inquiet', 'inquiete',
  'inquietude', 'je m inquiete', 'peur', 'j ai peur',
  'effrayé', 'effrayee', 'juge', 'jugee', 'jugement', 'pas assez bien',
  'doute', 'je doute', 'doute de soi', 'stress', 'stresse', 'stressée',
  'panique', 'erreur', 'erreurs', 'honte', 'embarrasse', 'embarrassee',
  'trop sensible', 'je reflechis trop', 'je suranalyse', 'besoin d etre rassure',
  'je garde pour moi', 'je cache mes emotions',
  'pression', 'tension', 'charge', 'chargé', 'chargee',
];

const strongAnxietyMarkers = [
  'panic', 'panic attack', 'intense anxiety', 'lose control', 'blocked',
  'mental fatigue', 'fear of failure', 'fear of judgment', 'overthinking',
  'panique', 'crise de panique', 'anxiete intense', 'angoisse',
  'perte de controle', 'bloque', 'bloquee',
  'fatigue mentale', 'peur de l echec',
  'peur du jugement', 'je suranalyse', 'je reflechis trop',
];

const regulationMarkers = [
  'calm', 'stay calm', 'breathe', 'breathing', 'pause', 'break',
  'organize', 'organized', 'step by step', 'small steps', 'plan',
  'calme', 'rester calme', 'respire', 'respirer', 'pause', 'pauses',
  'organise', 'organise', 'etape par etape', 'petites etapes',
  'planning', 'liste de taches', 'liste', 'priorisation', 'prioriser',
  'je fais de mon mieux', 'demander conseil', 'demande conseil',
  'corrige mes erreurs', 'je recommence', 'je m adapte',
];

const introversionMarkers = [
  'alone', 'prefer working alone', 'working alone', 'quiet', 'shy',
  'stay quiet', 'less attention', 'dont want attention',
  'hard to speak',
  'je prefere travailler seul', 'je prefere travailler seule',
  'je prefere rester seul', 'je prefere rester seule',
  'timide', 'je reste silencieux', 'je reste silencieuse', 'je parle peu',
  'difficile de parler', 'pas attirer l attention',
  'rester discret', 'rester discrete',
];

const socialPositiveMarkers = [
  'group', 'team', 'classmates', 'friends', 'share ideas', 'help others',
  'work with others', 'support', 'supervisor',
  'groupe', 'camarades', 'amis', 'encadrant', 'partager les idees',
  'aider les autres', 'travailler en groupe', 'voir mes amis', 'solution',
  'dialogue', 'dialoguer', 'conseil', 'conseils',
];

const organizationMarkers = [
  'organize', 'organized', 'schedule', 'plan', 'planning', 'priorities',
  'step by step', 'small tasks', 'deadline', 'urgent',
  'organiser', 'organise', 'planning', 'planifier', 'planification',
  'priorites', 'priorite', 'etape par etape', 'petites etapes',
  'liste', 'liste de taches', 'urgent', 'devoirs', 'pfe',
];

const agreeablenessMarkers = [
  'listen', 'supportive', 'calmly', 'without judgment', 'not judge',
  'understand', 'compromise', 'help others', 'solution', 'advice',
  'ecouter', 'j ecoute', 'soutien', 'sans juger', 'ne pas juger',
  'comprendre', 'compromis', 'calmement', 'respectueux', 'respectueuse',
  'aider les autres', 'trouver une solution', 'conseil', 'dialogue',
];

const opennessMarkers = [
  'curious', 'curiosity', 'learn', 'understand', 'new ideas', 'explore',
  'reflect', 'thoughts', 'practical', 'solutions',
  'curieux', 'curieuse', 'curiosite', 'apprendre', 'comprendre',
  'nouvelles idees', 'explorer', 'reflechir', 'pensees',
  'cours pratique', 'chercher des solutions', 'progres', 'competences',
];

function countMarkers(markers) {
  return markers.filter((marker) => {
    const raw = marker.toLowerCase();
    const normalized = raw.normalize('NFD').replace(/[̀-ͯ]/g, '');
    return conversationText.includes(raw) || normalizedConversationText.includes(normalized);
  }).length;
}

const anxietyCount = countMarkers(anxietyMarkers);
const strongAnxietyCount = countMarkers(strongAnxietyMarkers);
const regulationCount = countMarkers(regulationMarkers);
const introversionCount = countMarkers(introversionMarkers);
const socialPositiveCount = countMarkers(socialPositiveMarkers);
const organizationCount = countMarkers(organizationMarkers);
const agreeablenessCount = countMarkers(agreeablenessMarkers);
const opennessCount = countMarkers(opennessMarkers);

function normalizeName(name) {
  return String(name || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '');
}

function isTrait(t, target) {
  const n = normalizeName(t.name);
  const targetNorm = normalizeName(target);
  return n === targetNorm || n.includes(targetNorm);
}

function cleanTechnicalText(value) {
  return String(value || '')
    .replace(/Correction automatique\s*:[^.]*\./gi, '')
    .replace(/correction automatique\s*:[^.]*\./gi, '')
    .replace(/marqueurs detectes[^.]*\./gi, '')
    .replace(/regles de scoring[^.]*\./gi, '')
    .trim();
}

const unsupportedPhrases = [
  'difficulte a s ouvrir',
  'prendre du temps avant de s ouvrir',
  'difficulte a exprimer ses emotions',
  'difficulte a exprimer ses emotions',
  'etre ouvert a la relation',
  'etre ouvert a la relation',
  'peur de faire confiance',
  'prendre des risques',
  'nervosite dans ses interactions sociales',
  'nervosite dans ses interactions sociales',
  'retenue dans ses interactions sociales',
  'difficulte a se connecter aux autres',
  'difficulte a se connecter aux autres',
  'peur du jugement et a la suranalyse',
  'peur du jugement',
  'suranalyse',
];

function removeUnsupportedText(text) {
  let next = String(text || '');
  for (const phrase of unsupportedPhrases) {
    next = next.replace(new RegExp(phrase, 'gi'), '').trim();
  }
  return cleanTechnicalText(next);
}

if (traits.length !== 5) {
  errors.push(`Attendu 5 traits, recu ${traits.length}`);
}

for (const t of traits) {
  const score = Number(t.score || 0);
  if (!Number.isFinite(score) || score < 1 || score > 10) {
    errors.push(`${t.name}: score ${score} hors limites (1-10)`);
    t.score = Math.max(1, Math.min(10, Math.round(score || 5)));
  } else {
    t.score = Math.max(1, Math.min(10, Math.round(score)));
  }
  if (!t.analysis && !t.evidence) {
    warnings.push(`${t.name}: pas d'analyse ni d'evidence - confidence mise a faible`);
    t.confidence = 'faible';
    t.confidence_reason = isEN
      ? 'No direct usable data in the student responses.'
      : 'Aucune donnee directe exploitable dans les reponses';
  }
  t.analysis = removeUnsupportedText(t.analysis || '');
  t.interpretation = removeUnsupportedText(t.interpretation || '');
  t.evidence = removeUnsupportedText(t.evidence || '');
  if (!Array.isArray(t.observed_indicators)) {
    t.observed_indicators = [];
  }
  t.observed_indicators = t.observed_indicators
    .map((indicator) => removeUnsupportedText(indicator))
    .filter((indicator) => indicator.length > 0)
    .slice(0, 3);
  while (t.observed_indicators.length < 3) {
    t.observed_indicators.push(isEN
      ? 'Indicator to be confirmed with further concrete examples.'
      : 'Indicateur a confirmer par davantage d exemples concrets.');
  }
}

for (const t of traits) {
  if (isTrait(t, 'Neuroticisme')) {
    const currentScore = Number(t.score);
    if (strongAnxietyCount >= 2 && anxietyCount >= 4) {
      t.score = Math.max(7, Math.min(8, currentScore));
      t.confidence = 'moyen';
      t.confidence_reason = isEN
        ? 'Signs of more marked stress are present, but the score remains limited to explicitly observed elements.'
        : 'Des signes de stress plus marques sont presents, mais le score reste limite aux elements explicitement observes.';
      warnings.push(`Neuroticisme limite entre 7 et 8 : ${strongAnxietyCount} marqueurs forts detectes.`);
    } else if (anxietyCount >= 2 && regulationCount >= 2) {
      t.score = Math.min(6, currentScore);
      t.confidence = 'moyen';
      t.confidence_reason = isEN
        ? 'Stress is occasionally present, but the student describes several effective regulation strategies.'
        : 'Le stress est present de facon ponctuelle, mais l etudiant decrit plusieurs strategies de regulation efficaces.';
      warnings.push(`Neuroticisme limite a 6 : stress ponctuel avec ${regulationCount} marqueurs de regulation.`);
    } else if (anxietyCount >= 2) {
      t.score = Math.min(7, Math.max(5, currentScore));
      t.confidence = 'moyen';
      t.confidence_reason = isEN
        ? 'Some pressure indicators are present, without evidence of intense or lasting anxiety.'
        : 'Quelques indices de pression sont presents, sans preuve d anxiete intense ou durable.';
      warnings.push(`Neuroticisme ajuste entre 5 et 7 : ${anxietyCount} marqueurs de stress detectes.`);
    } else {
      t.score = Math.min(5, currentScore);
      t.confidence = 'faible';
      t.confidence_reason = isEN
        ? 'Few direct indicators of stress or emotional instability are present in the interview.'
        : 'Peu d indices directs de stress ou d instabilite emotionnelle sont presents dans l entretien.';
    }
    if (
      anxietyCount >= 1 ||
      normalizedConversationText.includes('charge') ||
      normalizedConversationText.includes('pfe') ||
      normalizedConversationText.includes('pression')
    ) {
      t.score = Math.max(4, Number(t.score));
    }
    if (Number(t.score) <= 6) {
      t.analysis = isEN
        ? 'The student describes occasional academic pressure, but also demonstrates strong regulation capacity through calmness, organization, and solution-seeking.'
        : 'L etudiant decrit une pression ponctuelle liee aux etudes, mais il montre aussi une bonne capacite de regulation grace au calme, a l organisation et a la recherche de solutions.';
      t.interpretation = isEN
        ? 'The observed level corresponds more to a low-to-moderate stress sensitivity than to high anxiety.'
        : 'Le niveau observe correspond davantage a une sensibilite faible a moderee au stress qu a une anxiete elevee.';
      t.observed_indicators = isEN
        ? [
            'Work period described as busy, with many tasks to organize.',
            'Good adaptation to unforeseen events: the student indicates easy adaptation or maintaining control.',
            'Regulation through organization: lists, prioritization of urgent tasks, and planned breaks.',
          ]
        : [
            'Periode de travail decrite comme chargee, avec beaucoup de taches a organiser.',
            'Bonne adaptation face aux imprevus : l etudiant indique qu il s adapte facilement ou qu il garde le controle.',
            'Regulation par l organisation : listes, priorisation des taches urgentes et pauses planifiees.',
          ];
    }
  }
  if (isTrait(t, 'Extraversion')) {
    if (introversionCount >= 3 && Number(t.score) > 5) {
      t.score = 5;
      t.confidence = 'moyen';
      t.confidence_reason = isEN
        ? 'Some reserve indicators are present, but insufficient to conclude strong introversion.'
        : 'Quelques indices de reserve sont presents, mais ils ne suffisent pas a conclure a une forte introversion.';
      warnings.push(`Extraversion ajustee a 5 : ${introversionCount} marqueurs d introversion detectes.`);
    }
    if (socialPositiveCount >= 2 && Number(t.score) < 5) {
      t.score = 5;
      t.confidence = 'moyen';
      t.confidence_reason = isEN
        ? 'The student mentions positive interactions with peers or the group.'
        : 'L etudiant mentionne des interactions positives avec les pairs ou le groupe.';
      warnings.push(`Extraversion remontee a 5 : ${socialPositiveCount} marqueurs sociaux positifs detectes.`);
    }
  }
  if (isTrait(t, 'Conscienciosite') && organizationCount >= 3 && Number(t.score) < 6) {
    t.score = 6;
    warnings.push(`Conscienciosite ajustee a 6 : ${organizationCount} marqueurs d organisation detectes.`);
  }
  if (isTrait(t, 'Agreabilite') && agreeablenessCount >= 3 && Number(t.score) < 6) {
    t.score = 6;
    warnings.push(`Agreabilite ajustee a 6 : ${agreeablenessCount} marqueurs relationnels positifs detectes.`);
  }
  if (isTrait(t, 'Ouverture') && opennessCount >= 3 && Number(t.score) < 6) {
    t.score = 6;
    warnings.push(`Ouverture ajustee a 6 : ${opennessCount} marqueurs d ouverture/introspection detectes.`);
  }
}

let scores = traits.map(t => Number(t.score));
let minScore = Math.min(...scores);
let maxScore = Math.max(...scores);
let spread = maxScore - minScore;

if (spread < 2) {
  warnings.push(`Spread trop faible (${spread}). Accentuation legere et prudente des ecarts.`);
  const conscientiousness = traits.find(t => isTrait(t, 'Conscienciosite'));
  const neuroticism = traits.find(t => isTrait(t, 'Neuroticisme'));
  if (conscientiousness) conscientiousness.score = Math.min(10, Number(conscientiousness.score) + 1);
  if (neuroticism) neuroticism.score = Math.max(1, Number(neuroticism.score) - 1);
}

scores = traits.map(t => Number(t.score));
minScore = Math.min(...scores);
maxScore = Math.max(...scores);
spread = maxScore - minScore;

const neuro = traits.find(t => isTrait(t, 'Neuroticisme'));
if (neuro && analysisData.emotional_profile) {
  const neuroScore = Number(neuro.score);
  analysisData.emotional_profile.emotional_stability = Math.max(1, Math.min(10, 11 - neuroScore));
  if (neuroScore >= 8) {
    analysisData.emotional_profile.dominant_emotion = isEN ? 'anxiety / worry' : 'anxiete / inquietude';
    analysisData.emotional_profile.emotional_summary = isEN
      ? 'The profile shows high emotional sensitivity, supported by several explicit signs of intense stress.'
      : 'Le profil montre une sensibilite emotionnelle elevee, appuyee par plusieurs signes explicites de stress intense.';
  } else if (neuroScore >= 6) {
    analysisData.emotional_profile.dominant_emotion = isEN ? 'moderate pressure' : 'pression moderee';
    analysisData.emotional_profile.emotional_summary = isEN
      ? 'The student occasionally feels pressure, but uses effective strategies such as organization, calmness, error correction, and seeking advice.'
      : 'L etudiant ressent parfois de la pression, mais il utilise des strategies efficaces comme l organisation, le calme, la correction des erreurs et la demande de conseil.';
  } else {
    analysisData.emotional_profile.dominant_emotion = isEN ? 'relative stability' : 'stabilite relative';
    analysisData.emotional_profile.emotional_summary = isEN
      ? 'The student shows relatively stable emotional regulation, with the ability to manage difficulties without major emotional overflow observed.'
      : 'L etudiant montre une regulation emotionnelle plutot stable, avec une capacite a gerer les difficultes sans debordement majeur observe.';
  }
}

analysisData.score_validation = {
  min_score: minScore,
  max_score: maxScore,
  spread,
  coherence_notes: warnings.length > 0 ? warnings.join(' | ') : 'Scores coherents.',
  validation_passed: errors.length === 0,
  errors,
  warnings,
  detected_markers: {
    anxietyCount,
    strongAnxietyCount,
    regulationCount,
    introversionCount,
    socialPositiveCount,
    organizationCount,
    agreeablenessCount,
    opennessCount,
  },
};

console.log('[VALIDATION] Scores:', traits.map(t => `${t.name}:${t.score}`).join(', '));
console.log('[VALIDATION] Marqueurs:', JSON.stringify(analysisData.score_validation.detected_markers));
console.log('[VALIDATION] Spread:', spread);
console.log('[VALIDATION] Erreurs:', errors.length, '| Warnings:', warnings.length);

return [{
  json: {
    output: JSON.stringify(analysisData),
    validationPassed: errors.length === 0,
    validationErrors: errors,
    validationWarnings: warnings,
  },
}];
